class Program
{
    static void Main(string[] args)
    {
        // Create a process and start it
        ProcessStartInfo startInfo = new ProcessStartInfo("notepad.exe");
        Process notepadProcess = Process.Start(startInfo);

        // Output some diagnostic information
        Console.WriteLine($"Process ID: {notepadProcess.Id}");

        // Use the Trace class to write to the debug output
        Trace.WriteLine("Application is running.");

        // Use a PerformanceCounter to track system metrics
